const proposal =
  $('Merge Slack Action and Stored Proposal').first().json || {};

const config =
  $('Approval Timeout Configuration').first().json || {};

const configuredTimeout = Number(config.approval_timeout_minutes);

const timeoutMinutes =
  Number.isFinite(configuredTimeout) && configuredTimeout > 0
    ? configuredTimeout
    : 5;

const createdAt = Date.parse(proposal.created_at || '');
const expiresAt = Date.parse(proposal.expires_at || '');
const now = Date.now();

const ageLimitMs = timeoutMinutes * 60 * 1000;
const ageMs = Number.isNaN(createdAt)
  ? NaN
  : now - createdAt;

const ageExpired =
  Number.isNaN(createdAt) ||
  ageMs < 0 ||
  ageMs > ageLimitMs;

const recordExpired =
  Number.isNaN(expiresAt) ||
  expiresAt <= now;

const approvalIsFresh =
  !ageExpired &&
  !recordExpired;

const expirationReason = Number.isNaN(createdAt)
  ? 'The database record has no valid created_at timestamp.'
  : Number.isNaN(expiresAt)
    ? 'The database record has no valid expires_at timestamp.'
    : recordExpired
      ? 'The database record expires_at timestamp has passed.'
      : ageExpired
        ? `The approval is ${Math.round(ageMs / 60000)} minute(s) old; the configured limit is ${timeoutMinutes} minute(s).`
        : '';

return [
  {
    json: {
      ...proposal,
      approval_timeout_minutes: timeoutMinutes,
      approval_age_minutes: Number.isNaN(ageMs)
        ? null
        : Math.round(ageMs / 60000),
      approval_is_fresh: approvalIsFresh,
      approval_expiration_reason: expirationReason,
      approval_error_message:
        `⌛️❌ This commit card is too old and has expired. ` +
        `${expirationReason} Please create a new request.`
    }
  }
];

