];

const incoming = $('Slack Mention Trigger').first().json;
const lookup = $('Lookup Slack Requester').first().json || {};
const slackUser = incoming.user || incoming.event?.user || '';
const profile = lookup.user || lookup.data?.user || lookup;
const raw = incoming.text || '';
const cleaned = raw.replace(/<@[^>]+>/g, '').trim();
const requesterUserId = typeof slackUser === 'string'
  ? slackUser
  : slackUser.id || incoming.user_id || incoming.event?.user_id || profile.id || '';
const requesterUserName = profile.profile?.display_name || profile.profile?.real_name || profile.real_name || profile.name || '';

return [{
  json: {
    text: cleaned,
    channel: incoming.channel,
    thread_ts: incoming.ts || incoming.event_ts,
    requester_user_id: requesterUserId,
    requester_user_name: requesterUserName || requesterUserId
  }
}];

/**
 * The node returns one n8n item whose `json` payload is:
 *
 * Read mode:
 * {
 *   ...src,
 *   mode: "read",
 *   proposals: [],
 *   proposal_validation: {
 *     status: "not_applicable",
 *     reason: "read mode request"
 *   }
 * }
 *
 * Commit mode:
 * {
 *   ...src,
 *   mode: "commit",
 *   cards: Array<originalCard + proposal metadata>,
 *   proposals: Array<normalized proposal objects>,
 *   proposal_validation: {
 *     status: "drafted",
 *     reason: "proposal objects built"
 *   }
 * }
 *
 * Returned to n8n as:
 * [{ json: <payload> }]
 */

/**
 * Source payload produced by previous planning step.
 * Expected fields include:
 * - mode: "read" | "commit"
 * - cards: array of candidate commit cards (commit mode)
 * - optional channel/thread context
 */
const src = items[0].json || {};

/**
 * Normalize mode strictly to two states:
 * - "commit" only when explicitly requested
 * - fallback to "read" for everything else
 */
const mode = src.mode === 'commit' ? 'commit' : 'read';

/**
 * Proposal timing metadata:
 * - proposal_created_at: current timestamp
 * - proposal_expires_at: created + ttlMinutes
 */
const now = new Date();
const ttlMinutes = 15;
const expires = new Date(now.getTime() + ttlMinutes * 60 * 1000);

/**
 * Generates a lightweight unique proposal ID.
 * Format: prop_<base36 timestamp>_<random suffix>
 * Example: prop_lm2x93_ab12cd
 */
const createProposalId = () => {
  const ts = Date.now().toString(36);
  const rnd = Math.random().toString(36).slice(2, 8);
  return 'prop_' + ts + '_' + rnd;
};

/**
 * Read mode short-circuit:
 * No proposal objects are created for read-only requests.
 * Validation is marked "not_applicable".
 */
if (mode !== 'commit') {
  return [{
    json: {
      ...src,
      mode: 'read',
      proposals: [],
      proposal_validation: { status: 'not_applicable', reason: 'read mode request' }
    }
  }];
}

/**
 * Commit mode:
 * - Ensure cards is always an array
 * - Enrich each card with proposal lifecycle metadata
 */
const cards = Array.isArray(src.cards) ? src.cards : [];
const structuredCards = cards.map((card) => ({
  ...card,
  proposal_id: createProposalId(),
  proposal_status: 'drafted',
  proposal_created_at: now.toISOString(),
  proposal_expires_at: expires.toISOString(),
  proposal_ttl_minutes: ttlMinutes
}));

/**
 * Build normalized `proposals` array:
 * This is a stable structure for downstream validation, gating,
 * auditing, and future persistence.
 */
const proposals = structuredCards.map((card) => ({
  proposal_id: card.proposal_id,
  proposal_status: card.proposal_status,
  proposal_created_at: card.proposal_created_at,
  proposal_expires_at: card.proposal_expires_at,
  channel: card.channel || src.channel || '',
  thread_ts: card.thread_ts || src.thread_ts || '',
  device: card.device || 'unknown',
  vendor: card.vendor || 'unknown',
  safety_reason: card.safety_reason || '',
  precheck_evidence: card.precheck_evidence || '',
  commit_payload: card.commit_payload || ''
}));

/**
 * Commit-mode output:
 * - keep original source fields
 * - replace cards with enriched cards
 * - attach normalized proposals
 * - set validation state to drafted (next node should validate)
 */
return [{
  json: {
    ...src,
    mode: 'commit',
    cards: structuredCards,
    proposals,
    proposal_validation: { status: 'drafted', reason: 'proposal objects built' }
  }
}];

const src = items[0].json || {};

if (src.mode !== 'commit') {
  return [{
    json: {
      ...src,
      mode: 'read',
      proposal_validation: { status: 'not_applicable', reason: 'read mode request' }
    }
  }];
}

const cards = Array.isArray(src.cards) ? src.cards : [];
if (cards.length === 0) {
  return [{
    json: {
      ...src,
      mode: 'read',
      cards: [],
      reply_markdown: '*Proposal validation failed:* no commit cards were generated. Please provide more specific change details and try again.',
      proposal_validation: { status: 'failed', reason: 'empty cards array' }
    }
  }];
}

const required = [
  'channel',
  'thread_ts',
  'device',
  'vendor',
  'safety_reason',
  'precheck_evidence',
  'commit_payload',
  'proposal_id',
  'proposal_created_at',
  'proposal_expires_at'
];

for (const card of cards) {
  for (const field of required) {
    if (!card[field] || String(card[field]).trim() === '') {
      return [{
        json: {
          ...src,
          mode: 'read',
          cards: [],
          reply_markdown: '*Proposal validation failed:* missing required field ' + field + ' for device ' + (card.device || 'unknown') + '.',
          proposal_validation: { status: 'failed', reason: 'missing field ' + field }
        }
      }];
    }
  }

  const expTs = Date.parse(card.proposal_expires_at);
  if (Number.isNaN(expTs) || expTs <= Date.now()) {
    return [{
      json: {
        ...src,
        mode: 'read',
        cards: [],
        reply_markdown: '*Proposal validation failed:* proposal expired or invalid for device ' + (card.device || 'unknown') + '.',
        proposal_validation: { status: 'failed', reason: 'invalid proposal ttl' }
      }
    }];
  }
}

return [{
  json: {
    ...src,
    mode: 'commit',
    cards: cards.map((c) => ({ ...c, proposal_status: 'validated' })),
    proposals: (Array.isArray(src.proposals) ? src.proposals : []).map((p) => ({ ...p, proposal_status: 'validated' })),
    proposal_validation: { status: 'validated', reason: 'schema and guardrails checks passed' }
  }
}];

